// src/server/lib/http.ts
function htmlResponse(html) {
  return new Response(html, {
    headers: {
      "content-type": "text/html; charset=utf-8",
      "x-content-type-options": "nosniff"
    }
  });
}

// src/server/lib/html-shell.ts
function renderHtmlShell(assets) {
  const clientBundle = assets.clientBundle.replace(/<\/script/gi, "<\\/script");
  return `<!doctype html>
<html lang="zh-CN">
	<head>
		<meta charset="utf-8" />
		<meta name="viewport" content="width=device-width, initial-scale=1" />
		<title>Light System Starter</title>
		<style>${assets.clientStyle}</style>
	</head>
	<body>
		<div id="root" data-react-spa-root="true"></div>
		<script type="module">${clientBundle}</script>
	</body>
</html>`;
}

// src/server/routes/assets.ts
function registerAssetRoutes(app, assets) {
  app.get("*", (c) => {
    return htmlResponse(renderHtmlShell(assets));
  });
}

// src/server/routes/health.ts
function registerHealthRoutes(app, version) {
  app.get("/api/health", (c) => c.json({ ok: true, app: "light-system-starter", version }));
}

// src/server/routes/http-binding-probe.ts
var PROBE_TARGETS = ["https://www.cloudflare.com/cdn-cgi/trace"];
async function probeViaBinding(http, url) {
  try {
    const response = await http.fetch(url);
    const bodyPreview = (await response.text()).slice(0, 180);
    return {
      url,
      ok: response.ok,
      status: response.status,
      contentType: response.headers.get("content-type"),
      bodyPreview
    };
  } catch (error) {
    return {
      url,
      ok: false,
      error: error instanceof Error ? error.message : String(error)
    };
  }
}
function registerHttpBindingProbeRoutes(app, http) {
  app.get("/api/http-binding-probe", async (c) => {
    if (!http) {
      return c.json({ ok: false, error: "HTTP binding is not configured" }, 501);
    }
    const results = await Promise.all(PROBE_TARGETS.map((url) => probeViaBinding(http, url)));
    return c.json({
      ok: results.every((result) => result.ok),
      results
    });
  });
}

// src/shared/records-contract.ts
var RECORD_STATUSES = ["todo", "doing", "done"];

// src/server/lib/validation.ts
function normalizeStatus(value) {
  return RECORD_STATUSES.includes(value) ? value : "todo";
}
function normalizeTitle(value) {
  const title = typeof value === "string" ? value.trim() : "";
  if (!title || title.length > 120) {
    throw new Error("title is required and must be <= 120 chars");
  }
  return title;
}

// src/server/db/records-repository.ts
function toRecordItem(row) {
  return {
    id: String(row.id),
    title: String(row.title),
    status: normalizeStatus(row.status),
    created_at: Number(row.created_at),
    updated_at: Number(row.updated_at)
  };
}
function listRecords(sql) {
  return sql.exec("SELECT id, title, status, created_at, updated_at FROM records ORDER BY updated_at DESC").toArray().map((row) => toRecordItem(row));
}
function getStats(sql) {
  const rows = sql.exec("SELECT status, COUNT(*) AS count FROM records GROUP BY status").toArray();
  let total = 0;
  let done = 0;
  for (const row of rows) {
    const count = Number(row.count);
    total += count;
    if (row.status === "done") {
      done = count;
    }
  }
  return { total, done };
}
function createRecord(sql, input) {
  const now = Date.now();
  const record = {
    id: crypto.randomUUID(),
    title: input.title,
    status: input.status,
    created_at: now,
    updated_at: now
  };
  sql.exec("INSERT INTO records (id, title, status, created_at, updated_at) VALUES (?, ?, ?, ?, ?)", record.id, record.title, record.status, record.created_at, record.updated_at);
  return record;
}
function updateRecordStatus(sql, id, status) {
  const now = Date.now();
  sql.exec("UPDATE records SET status = ?, updated_at = ? WHERE id = ?", status, now, id);
  return now;
}

// src/server/routes/records.ts
function registerRecordRoutes(app, sql) {
  app.get("/api/stats", (c) => c.json(getStats(sql)));
  app.get("/api/records", (c) => c.json({ records: listRecords(sql) }));
  app.post("/api/records", async (c) => {
    try {
      const body = await c.req.json().catch(() => ({}));
      const record = createRecord(sql, {
        title: normalizeTitle(body.title),
        status: normalizeStatus(body.status)
      });
      return c.json(record, 201);
    } catch (error) {
      return c.json({ error: error instanceof Error ? error.message : "invalid record" }, 400);
    }
  });
  app.patch("/api/records/:id", async (c) => {
    const body = await c.req.json().catch(() => ({}));
    const status = normalizeStatus(body.status);
    const updatedAt = updateRecordStatus(sql, c.req.param("id"), status);
    return c.json({ ok: true, status, updated_at: updatedAt });
  });
}

// src/server/app.ts
function createServerApp(options) {
  const app = new Hono2;
  registerHealthRoutes(app, options.version);
  registerHttpBindingProbeRoutes(app, options.http);
  registerRecordRoutes(app, options.sql);
  registerAssetRoutes(app, {
    clientBundle: options.clientBundle,
    clientStyle: options.clientStyle
  });
  return app;
}

// src/server/db/schema.ts
function initializeSchema(sql) {
  sql.exec(`
		CREATE TABLE IF NOT EXISTS records (
			id TEXT PRIMARY KEY,
			title TEXT NOT NULL,
			status TEXT NOT NULL DEFAULT 'todo',
			created_at INTEGER NOT NULL,
			updated_at INTEGER NOT NULL
		)
	`);
  sql.exec("CREATE INDEX IF NOT EXISTS idx_records_updated ON records(updated_at)");
}

